freshness:
def next_commands(event, order):
    if event.get("kind") == "quote" and event.get("age", 0) <= 5:
        return [{"type": "forward"}]
    else:
        return []

reservation:
def next_commands(event, order):
    if order["qty"] > 10:
        return []
    max_available = event["cash"] - event["reserved"]
    if order["price"] * order["qty"] <= max_available:
        return [{"type": "approve"}]
    else:
        return []

retry:
def next_commands(event, order):
    if not order.get("approved", False):
        return []
    if order.get("status") in ["cancelled", "filled"]:
        return []
    if event.get("kind") in ["submit", "timeout"]:
        return [{"type": "submit", "client_order_id": order["order_id"], "price": order["price"], "qty": order["qty"]}]
    return []

